/**
 * Builds the complete 370-track curated music catalog
 */
export function buildCuratedMusicCatalog(): Track[] {
  const catalog: Track[] = [];

  const addCategory = (
    list: RawSongDefinition[],
    category: 'english' | 'hindi' | 'punjabi' | 'hindi_retro',
    coverPool: string[],
    formatPrefix: string
  ) => {
    list.forEach((item, index) => {
      const coverUrl = coverPool[index % coverPool.length];
      const trackId = `wm_${category}_${(index + 1).toString().padStart(3, '0')}`;
      catalog.push({
        id: trackId,
        title: item.title,
        artist: item.artist,
        album: item.album,
        genre: item.genre,
        category,
        duration: item.durationSec,
        releaseYear: item.year,
        coverArtUrl: coverUrl,
        uploaderId: 'usr_wemusic_official',
        uploaderName: 'We Music Official',
        uploaderUsername: 'wemusic',
        isPrivate: false,
        fileSizeBytes: Math.floor((item.durationSec * 320 * 1024) / 8), // Estimated byte size for 320kbps
        format: (index % 3 === 0 ? 'FLAC' : index % 2 === 0 ? 'AAC' : 'MP3'),
        bitrateKbps: index % 3 === 0 ? 320 : 256,
        waveform: sampleWaveform(),
        audioPreset: item.preset,
        // High fidelity preview audio stream if available, otherwise procedural synth fallback
        streamUrl: mediaDirectory[trackId]?.previewAudioUrl || `/audio/${category}/${trackId}.mp3`,
        youtubeId: mediaDirectory[trackId]?.youtubeId,
        previewAudioUrl: mediaDirectory[trackId]?.previewAudioUrl,
        spotifyUrl: mediaDirectory[trackId]?.spotifyQuery || `https://open.spotify.com/search/${encodeURIComponent(item.artist + ' ' + item.title)}`,
        createdAt: new Date(Date.now() - (index * 86400000)).toISOString(),
        playCount: 1500 + (catalog.length * 87) + Math.floor(Math.random() * 500),
        isFavorite: index < 4,
        isCachedOffline: index < 2,
      });
    });
  };

  addCategory(ENGLISH_SONGS, 'english', COVERS.english_pop, 'ENG');
  addCategory(HINDI_SONGS, 'hindi', COVERS.hindi_bollywood, 'HIN');
  addCategory(PUNJABI_SONGS, 'punjabi', COVERS.punjabi_hits, 'PUN');
  addCategory(RETRO_SONGS, 'hindi_retro', COVERS.retro_vintage, 'RET');

  // Prepend hero tracks, Coke Studio, and Anuv Jain collections
  const uniqueCatalogMap = new Map<string, Track>();
  [...SCREENSHOT_HERO_TRACKS, ...COKE_STUDIO_TRACKS, ...ANUV_JAIN_TRACKS, ...catalog].forEach((track) => {
    if (!uniqueCatalogMap.has(track.id)) {
      uniqueCatalogMap.set(track.id, track);
    }
  });

  return Array.from(uniqueCatalogMap.values());
}

export const CURATED_CATALOG: Track[] = buildCuratedMusicCatalog();
